        internal static string TranslateDiagnostic(string value, int language)
        {
            if (language <= 0 || string.IsNullOrEmpty(value)) return value;
            // Translate screen output only, never preflight values, generated names or saved data.
            value = Translate(value, language);
            foreach (var pair in DiagnosticPhrases)
            {
                if (value.IndexOf(pair.Key, StringComparison.Ordinal) >= 0)
                    value = value.Replace(pair.Key, pair.Value[language == 1 ? 0 : 1]);
            }
            return value;
        }

        internal static string Translate(string chinese, int language)
        {
            if (language <= 0 || string.IsNullOrEmpty(chinese)) return chinese;
            string[] values;
            if (!Strings.TryGetValue(chinese, out values)) return chinese;
            return language == 1 ? values[0] : values[1];
        }
    }
